<?php
namespace App\Http\Middleware;use App\Models\ActivityLog;use Closure;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\Response;use Throwable;
class RecordActivity{public function handle(Request $request,Closure $next):Response{$response=$next($request);$user=$request->user();if($user&&in_array($request->method(),['POST','PUT','PATCH','DELETE'])&&$response->getStatusCode()<500){try{$companyId=$user->account_type==='company'?$user->companies()->wherePivot('status','active')->value('companies.id'):null;ActivityLog::create(['user_id'=>$user->id,'company_id'=>$companyId,'action'=>strtolower($request->method()).':'.$request->route()?->uri(),'method'=>$request->method(),'path'=>'/'.$request->path(),'response_status'=>$response->getStatusCode(),'ip_address'=>$request->ip(),'user_agent'=>mb_substr((string)$request->userAgent(),0,500),'context'=>['route_parameters'=>collect($request->route()?->parameters()??[])->map(fn($v)=>is_object($v)&&isset($v->id)?$v->id:$v)->all()]]);}catch(Throwable){}}return $response;}}
